import { test as setup, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';

const authFile = '.auth/user.json';

// Log in ONCE through the UI, then save cookies + localStorage.
setup('authenticate', async ({ page }) => {
  const login = new LoginPage(page);
  await login.goto();
  // Secrets come from environment, never from source control.
  await login.login(process.env.BANK_USER!, process.env.BANK_PASS!);

  // Auto-waiting web-first assertion: no hard sleep.
  await expect(page.getByRole('heading', { name: /welcome, rajesh/i })).toBeVisible();

  await page.context().storageState({ path: authFile });
});
