// ─── File: tests/login.spec.ts ───
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/LoginPage';

// This spec exercises the REAL login flow (not reusing saved state),
// so it runs without storageState to test the form itself.
test.use({ storageState: { cookies: [], origins: [] } });

test.describe('Login page', () => {
  test('positive: valid credentials reach the dashboard', async ({ page }) => {
    const login = new LoginPage(page);
    await login.goto();
    await login.login(process.env.BANK_USER!, process.env.BANK_PASS!);

    // Assert a reliable success signal, with auto-waiting.
    await expect(page).toHaveURL(/.*\/dashboard/);
    await expect(page.getByRole('heading', { name: /welcome, rajesh/i })).toBeVisible();
    await expect(page.getByTestId('account-balance')).toContainText('950,000');
  });

  test('negative: invalid password is rejected and stays on login', async ({ page }) => {
    const login = new LoginPage(page);
    await login.goto();
    await login.login(process.env.BANK_USER!, 'WrongPassword!');

    // Explicit failed-login assertions.
    await expect(login.error).toHaveText(/invalid username or password/i);
    await expect(page).toHaveURL(/.*\/login/);          // did NOT navigate away
    await expect(page.getByTestId('account-balance')).toHaveCount(0); // no authed content
  });
});
